// Phase 5 TEST LIST item 2: the generated manifest src/content/projectImages.js and the image helpers
// in projects.js. The manifest is generated by scripts/optimize-images.mjs, so until that runs these fail.
import { describe, it, expect } from 'vitest'
import { readFileSync, existsSync, readdirSync } from 'node:fs'
import { resolve } from 'node:path'
import { PROJECTS, projectImage, projectSrcSet, projectDims, projectFull } from './index.js'
import { PROJECT_IMAGES } from './projectImages.js'

const root = process.cwd()
const ORIGINALS = resolve(root, 'design/img/originals')
const IMAGE_NAMES = PROJECTS.map((p) => p.image)

// Width and height from the IHDR chunk of a PNG (bytes 16–23, big-endian).
function pngSize(file) {
  const b = readFileSync(file)
  expect(b.subarray(1, 4).toString('ascii')).toBe('PNG')
  return { w: b.readUInt32BE(16), h: b.readUInt32BE(20) }
}

// Non-test source files under src/ (test files may name the old paths).
function sourceFiles(dir = resolve(root, 'src')) {
  const out = []
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const p = resolve(dir, entry.name)
    if (entry.isDirectory()) out.push(...sourceFiles(p))
    else if (/\.(m?js|jsx)$/.test(entry.name) && !/\.test\.[a-z]+$/.test(entry.name)) out.push(p)
  }
  return out
}

describe('project image manifest (phase 5)', () => {
  it('has exactly one entry per PROJECTS image name', () => {
    expect(Object.keys(PROJECT_IMAGES).sort()).toEqual([...new Set(IMAGE_NAMES)].sort())
  })

  it('every entry has positive natural w and h and at least one file', () => {
    for (const name of IMAGE_NAMES) {
      expect(PROJECT_IMAGES[name].w, name).toBeGreaterThan(0)
      expect(PROJECT_IMAGES[name].h, name).toBeGreaterThan(0)
      expect(PROJECT_IMAGES[name].files.length, name).toBeGreaterThan(0)
    }
  })

  it('file widths are strictly ascending, never wider than the natural width, and named <name>-<width>.webp', () => {
    for (const name of IMAGE_NAMES) {
      const { w, files } = PROJECT_IMAGES[name]
      let prev = 0
      for (const [width, path] of files) {
        expect(width, name).toBeGreaterThan(prev)
        expect(width, name).toBeLessThanOrEqual(w)
        expect(path, name).toBe(`/img/projects/${name}-${width}.webp`)
        prev = width
      }
    }
  })

  it('every listed file exists under public/', () => {
    for (const name of IMAGE_NAMES) {
      for (const [, path] of PROJECT_IMAGES[name].files) {
        expect(existsSync(resolve(root, 'public' + path)), path).toBe(true)
      }
    }
  })

  it('for an original wider than 1280 px, the largest file is at least 1280 px wide', () => {
    for (const name of IMAGE_NAMES) {
      const { w, files } = PROJECT_IMAGES[name]
      if (w > 1280) expect(files.at(-1)[0], name).toBeGreaterThanOrEqual(1280)
    }
  })

  it('w and h match the original PNG in design/img/originals/ (only joblog may lack one)', () => {
    for (const name of IMAGE_NAMES) {
      const png = resolve(ORIGINALS, name + '.png')
      if (existsSync(png)) {
        expect(pngSize(png), name).toEqual({ w: PROJECT_IMAGES[name].w, h: PROJECT_IMAGES[name].h })
      } else {
        expect(name, 'only joblog may lack an original').toBe('joblog')
      }
    }
  })

  it('no source file still uses the old single-file naming /img/projects/<name>.webp', () => {
    const offenders = sourceFiles().filter((f) => /\/img\/projects\/[a-z]+\.webp/.test(readFileSync(f, 'utf8')))
    expect(offenders).toEqual([])
  })
})

describe('project image helpers (phase 5)', () => {
  const RW = PROJECTS[0]
  const DUO = PROJECTS.find((p) => p.image === 'duonosaur')

  it('projectImage is the smallest file; projectFull is the largest', () => {
    expect(projectImage(RW)).toBe('/img/projects/recyclewise-640.webp')
    expect(projectFull(RW)).toBe('/img/projects/recyclewise-1920.webp')
    expect(projectFull(DUO)).toBe('/img/projects/duonosaur-640.webp')
  })

  it('projectSrcSet lists every file up to maxW, and all files when maxW is omitted', () => {
    expect(projectSrcSet(RW)).toBe(
      '/img/projects/recyclewise-640.webp 640w, /img/projects/recyclewise-1280.webp 1280w, /img/projects/recyclewise-1920.webp 1920w',
    )
    expect(projectSrcSet(RW, 1280)).toBe('/img/projects/recyclewise-640.webp 640w, /img/projects/recyclewise-1280.webp 1280w')
    expect(projectSrcSet(RW, 1280)).not.toContain('1920w')
  })

  it('projectDims is the natural size of the original (portrait Duonosaur too)', () => {
    expect(projectDims(RW)).toEqual({ w: 3356, h: 1798 })
    expect(projectDims(DUO)).toEqual({ w: 704, h: 1538 })
  })

  it('every project resolves a srcset, a src and dims', () => {
    for (const p of PROJECTS) {
      expect(projectSrcSet(p), p.title).toMatch(/ \d+w/)
      expect(projectImage(p), p.title).toMatch(/^\/img\/projects\//)
      expect(projectDims(p).w, p.title).toBeGreaterThan(0)
    }
  })
})
